INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Ist die Wahl eines nicht überlappenden Kanals bei der WLAN-Einrichtung wichtig?', 2, '[{"text": "Ja", "correct": true, "because": "Vermeidet Interferenzen"}, {"text": "Nein", "correct": false, "because": "Kanalwahl beeinflusst Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein WLAN-Netzwerk ohne Zuweisung einer SSID betrieben werden?', 2, '[{"text": "Nein", "correct": true, "because": "SSID ist zur Identifikation nötig"}, {"text": "Ja", "correct": false, "because": "SSID muss definiert sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Access Point mit einem Router verbunden sein, um Internetzugang zu bieten?', 2, '[{"text": "Ja", "correct": true, "because": "Router stellt Internetverbindung her"}, {"text": "Nein", "correct": false, "because": "Ohne Router kein Internet"}]'),
('00000000-0000-0000-0000-000000000000', 'Können mehrere Access Points mit derselben SSID in einem Netzwerk eingerichtet werden?', 2, '[{"text": "Ja", "correct": true, "because": "Ermöglicht Roaming"}, {"text": "Nein", "correct": false, "because": "Mehrere APs sind üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist WPA3 abwärtskompatibel mit älteren WLAN-Standards wie WPA2?', 2, '[{"text": "Ja", "correct": true, "because": "WPA3 unterstützt oft WPA2-Geräte"}, {"text": "Nein", "correct": false, "because": "Kompatibilität ist gegeben"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Frequenzbereich bietet weniger Störungen durch benachbarte Netzwerke?', 2, '[{"text": "5 GHz", "correct": true, "because": "Weniger genutzt als 2,4 GHz"}, {"text": "2,4 GHz", "correct": false, "because": "Häufiger überlastet"}, {"text": "60 GHz", "correct": false, "because": "Spezialisierte Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einstellung sollte bei der WLAN-Einrichtung angepasst werden, um Interferenzen zu minimieren?', 3, '[{"text": "Kanal", "correct": true, "because": "Nicht überlappende Kanäle reduzieren Störungen"}, {"text": "SSID", "correct": false, "because": "Nur Identifikation"}, {"text": "Frequenzbandbreite", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsmethode sollte bei der Einrichtung eines neuen WLANs bevorzugt werden?', 2, '[{"text": "WPA3", "correct": true, "because": "Aktuellster und sicherster Standard"}, {"text": "WPA2", "correct": false, "because": "Älter, aber sicher"}, {"text": "WEP", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher WLAN-Standard ist für hohe Dichte und Effizienz optimiert?', 2, '[{"text": "802.11ax (Wi-Fi 6)", "correct": true, "because": "Bietet OFDMA und MU-MIMO"}, {"text": "802.11n", "correct": false, "because": "Älter, weniger effizient"}, {"text": "802.11ac", "correct": false, "because": "Wi-Fi 5, weniger optimiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente muss bei der WLAN-Einrichtung die SSID bereitstellen?', 2, '[{"text": "Access Point", "correct": true, "because": "AP definiert das Netzwerk"}, {"text": "Router", "correct": false, "because": "Router ergänzt, aber nicht primär"}, {"text": "Switch", "correct": false, "because": "Keine WLAN-Funktion"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Parameter sollten bei der WLAN-Einrichtung konfiguriert werden?', 4, '[{"text": "SSID", "correct": true, "because": "Netzwerkidentifikation"}, {"text": "Verschlüsselung", "correct": true, "because": "z. B. WPA3 für Sicherheit"}, {"text": "Kanal", "correct": true, "because": "Vermeidet Interferenzen"}, {"text": "Bildschirmhelligkeit", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Frequenzbänder können bei der WLAN-Einrichtung ausgewählt werden?', 3, '[{"text": "2,4 GHz", "correct": true, "because": "Große Reichweite"}, {"text": "5 GHz", "correct": true, "because": "Hohe Geschwindigkeit"}, {"text": "60 GHz", "correct": true, "because": "Für 802.11ad/ay"}, {"text": "10 GHz", "correct": false, "because": "Nicht für WLAN"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Sicherheitsoptionen sind bei der WLAN-Einrichtung sinnvoll?', 4, '[{"text": "WPA3", "correct": true, "because": "Höchste Sicherheit"}, {"text": "MAC-Filter", "correct": true, "because": "Beschränkt Zugriff"}, {"text": "SSID ausblenden", "correct": true, "because": "Erschwert Auffinden"}, {"text": "Kein Passwort", "correct": false, "because": "Unsicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten sind bei der Einrichtung eines WLAN-Netzwerks beteiligt?', 3, '[{"text": "Access Point", "correct": true, "because": "Zentrale Verbindung"}, {"text": "Router", "correct": true, "because": "Für Internetzugang"}, {"text": "WLAN-Adapter", "correct": true, "because": "Für Client-Geräte"}, {"text": "Koaxialkabel", "correct": false, "because": "Nicht für WLAN"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte sollten bei der Kanalwahl für die WLAN-Einrichtung beachtet werden?', 3, '[{"text": "Nicht überlappende Kanäle", "correct": true, "because": "Reduziert Interferenzen"}, {"text": "Signalstärke benachbarter Netze", "correct": true, "because": "Beeinflusst Störungen"}, {"text": "Kanalbreite", "correct": true, "because": "z. B. 20 MHz oder 40 MHz"}, {"text": "Farbe des Access Points", "correct": false, "because": "Irrelevant"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) WPA3 bietet höhere Sicherheit als WPA2. b) Ein WLAN-Netzwerk kann ohne Access Point eingerichtet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "WPA3 ja, AP nötig (außer Ad-hoc)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Die SSID muss bei der WLAN-Einrichtung eindeutig sein. b) 2,4 GHz hat eine geringere Reichweite als 5 GHz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "SSID eindeutig ja, 2,4 GHz größere Reichweite"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Mehrere Access Points mit derselben SSID ermöglichen Roaming. b) WPA3 ist mit allen alten Geräten kompatibel.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Roaming ja, WPA3 nicht voll kompatibel"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Die Kanalwahl kann die WLAN-Leistung verbessern. b) Ein Router ist für ein lokales WLAN-Netzwerk ohne Internet ausreichend.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Kanalwahl ja, Router kann lokal dienen"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist auch richtig"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist auch richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) 802.11ax unterstützt höhere Dichten als 802.11ac. b) Die SSID muss bei der Einrichtung sichtbar bleiben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "802.11ax ja, SSID kann ausgeblendet werden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

